sortFunctions.bubble = function bubbleSort(A) {
	let swapped = true
	while (swapped) {
		swapped = false
		for (let i = 1; i < A.length; i++) {
			if (A[i - 1] > A[i]) {
				arrays.push(A.slice())

				//swap
