}

// === Tab: insertion sort ===
sortFunctions.insertion = function insertionSort(A) {
	for (let i = 0; i < A.length; i++) {

		let j = i;
		while (j > 0 && A[j - 1] > A[j]) {
			arrays.push(A.slice())

			//swap
			;[A[j], A[j-1]] = [A[j-1], A[j]]

			j--
		}
	}
	return A
}

// === Tab: quick sort ===
sortFunctions.quick = function quickSort(A, lo, hi) {
	if (lo < hi) {
		let p = partition(A, lo, hi)
		quickSort(A, lo, p)
		quickSort(A, p + 1, hi)
	}
	return A

	function partition(A, lo, hi) {
		let pivot = A[floor((hi + lo) / 2)]
		let i = lo - 1
		let j = hi + 1
		while (true) {

			i++
			while (A[i] < pivot) {
				i++
			}

			j--
			while (A[j] > pivot) {
				j--
			}

			if (i >= j) {
				return j
			}

			arrays.push(A.slice())

			//swap
			;[A[i], A[j]] = [A[j], A[i]]	
		}
	}


}

// === Tab: heap sort ===
sortFunctions.heap = function heapsort(A) {
	heapify(A)

	let end = A.length - 1
	while (end > 0) {
		arrays.push(A.slice());
		let temp = A[end];
		A[end] = A[0];
		A[0] = temp;
		end--;
		siftDown(A, 0, end)
	}

	return A;

}

function heapify(A) {
	let start = iParent(A.length - 1);

	while (start >= 0) {
		siftDown(A, start, A.length - 1);
		start = start - 1;
	}
}

function siftDown(A, start, end) {
	root = start;

	while (iLeftChild(root) < end) {
		child = iLeftChild(root);
		swap = root;

		if (A[swap] < A[child]) {
			swap = child;
		}
		if (child + 1 <= end && A[swap] < A[child + 1]) {
			swap = child + 1;
		}
		if (swap === root) {
			return;
		} else {
			arrays.push(A.slice());

			//swap
			[A[root], A[swap]] = [A[swap], A[root]];

			root = swap;
		}
	}
}

let iParent = (i) => floor((i - 1) / 2);
let iLeftChild = (i) => 2 * i + 1;
let iRightChild = (i) => 2 * i + 2;

// === Tab: selection sort ===
sortFunctions.selection = function selectionSort(A) {
	for (let i = 0; i < A.length - 1; i++) {
		let jMin = i;

		for (let j = i + 1; j < A.length; j++) {
			if (A[j] < A[jMin]) {
				jMin = j;
			}
		}

		if (jMin != i) {
			arrays.push(A.slice());

			//swap
			[A[i], A[jMin]] = [A[jMin], A[i]];
		}

	}

	return A;
}


// === Tab: gnome sort ===
sortFunctions.gnome = function gnomeSort(A) {
	let pos = 0
	while (pos < A.length) {
		if (pos === 0 || A[pos] >= A[pos - 1]) {
			pos++
		} else {
			[A[pos], A[pos - 1]] = [A[pos - 1], A[pos]]

			pos--
		}
		arrays.push(A.slice())
	}

	return A
}

// === Tab: comb sort ===
sortFunctions.comb = function combSort(A) {

	let gap = A.length // Initialize gap size
	const shrink = 1.3 // Set the gap shrink factor
	let sorted = false

	while (!sorted) {
		// Update the gap value for a next comb
		gap = floor(gap / shrink);
		if (gap <= 1) {
			gap = 1
			sorted = true // If there are no swaps this pass, we are done
		}

		// A single "comb" over the input list
		let i = 0
		while (i + gap < A.length) { // See Shell sort for a similar idea
			if (A[i] > A[i + gap]) {
				[A[i], A[i+gap]] = [A[i+gap],A[i]]

				sorted = false
				// If this assignment never happens within the loop,
				// then there have been no swaps and the list is sorted.
				arrays.push(A.slice())
			}

			i++
		}
	}

}

// === Tab: interpolation sort ===
sortFunctions.interpolation = function interpolationSort(A) {
	let divideSize = []
	let end = A.length
	divideSize[0] = end
	while (divideSize.length > 0) {
		divide(A)
	}

	function divide(A) {
		let size = divideSize.pop()
		let start = end - size;
		let min = A[start]
		let max = A[start]
		let temp = 0
		for (let i = start + 1; i < end; i++) {
			if (A[i] < min) {
				min = A[i]
			} else {
				if (A[i] > max) {
					max = A[i]
				}
			}
		}
		if (min === max) {
			end -= size;
		} else {
			var p = 0
			var bucket = []
			for (var i = 0; i < size; i++) {
				bucket[i] = []
			}
			for (let i = start; i < end; i++) {
				p = Math.floor(((A[i] - min) / (max - min)) * (size - 1))
				bucket[p].push(A[i])
			}

			for (let i = 0; i < size; i++) {
				if (bucket[i].length > 0) {
					for (let j = 0; j < bucket[i].length; j++) {
						A[start++] = bucket[i][j]

					}
					divideSize.push(bucket[i].length)
				}
				arrays.push(A.slice())

			}
		}
	}
}

