		return A;
	}

	let middleIndex = floor(A.length/2);
	let left = A.slice(0, middleIndex);
	let right = A.slice(middleIndex, A.length);

	left = mergeSort(left, recusionLevel+1);
	right = mergeSort(right, recusionLevel+1);

	if(arrays[recusionLevel] === undefined){
		arrays[recusionLevel] = A;
	}else{
		arrays[recusionLevel].concat(A);
	}

	return merge(left, right);
}

function merge(left, right) {
	let result = [];

	while (left.length > 0 && right.length > 0) {
		if (left[0] <= right[0]) {
			result.push(left.shift());
		} else {
			result.push(right.shift());
		}
	}

	if (left.length > 0) {
		result.push(left.slice());
	}
	if (right.length > 0) {
		result.push(right.slice());
	}
	return result;
}


