const sortTypes = ["bubble", "insertion", "quick", "heap", "selection", "gnome", "comb", "merge", "bogo"];

let sortFunctions = {}

let settings = {
	arrayOrdering: "random",
	arrayLength: 50,
	sortType: "quick",
	seed: 100,

	extraLinesAtBeginningAndEnd: true,
	curvyLines: false,
	scale: 0.98,
	strokeThickness: 4,
	lerpBetweenColors: true,
	colorScheme: "poppa",
	backgroundColor: colorSchemes["poppa"].backgroundColor,
	//alpha: 175, //0 to 255;

	save: saveImage
}

let arrays = []

function setup() {
	settings.seed = floor(random(100000))
	noFill()
	createCanvas(sqrt(2)*windowHeight, windowHeight)
	createGUI()
	createNewImage()
}

function createNewImage() {
	updateSortArrays()
	display()
}

function updateSortArrays() {
	randomSeed(settings.seed)

	let arrayToSort = []
	for (let i = 0; i < settings.arrayLength; i++) {
		switch (settings.arrayOrdering) {
			case "reverse":
				arrayToSort.push(settings.arrayLength - i + 1)
				break

			case "numbers 1 to 10" || "1 to 10":
				arrayToSort.push(floor(random(10)))
				break

			case "odds then evens":
				let a = (i <= settings.arrayLength / 2 ? i * 2 + 1 : (i % (ceil(settings.arrayLength / 2))) * 2)
				console.log(a)
				arrayToSort.push(a)
				break

			default:
				arrayToSort.push(i)
				break
		}
	}
	if (settings.arrayOrdering === "random") arrayToSort = shuffle(arrayToSort)

	arrays = []
	if (settings.sortType === "quick") {
		sortFunctions.quick(arrayToSort, 0, arrayToSort.length - 1)
	} else {
		sortFunctions[settings.sortType](arrayToSort)
	}

	if (arrays.length === 0) arrays.push(arrayToSort.slice())

	arrays.push(arrayToSort.slice())

	return arrays
}

function display() {
	push()
	translate(width / 2, height / 2);
	scale(settings.scale);
	translate(-width / 2, -height / 2);
	background(settings.backgroundColor)
	strokeWeight(settings.strokeThickness)
	let xSpacing = settings.extraLinesAtBeginningAndEnd ? width / (arrays.length + 3) : width / (arrays.length + 1)
	let ySpacing = height / (arrays[0].length + 1)

	let itemIndex = 0
	for (let item of arrays[arrays.length - 1]) { //noprotect

		let lineColor;
		if (settings.lerpBetweenColors) {
			let i = itemIndex / (arrays[arrays.length - 1].length) * (colorSchemes[settings.colorScheme].colors.length - 1)
			let color1 = color(colorSchemes[settings.colorScheme].colors[floor(i)])
			let color2 = color(colorSchemes[settings.colorScheme].colors[floor(i) + 1])
			lineColor = lerpColor(color1, color2, i % 1)
		} else {
			lineColor = colorSchemes[settings.colorScheme].colors[itemIndex % colorSchemes[settings.colorScheme].colors.length]
		}

		//lineColor.setAlpha(settings.alpha)
		stroke(lineColor)
		strokeCap(SQUARE);

		beginShape();
		if (settings.extraLinesAtBeginningAndEnd) {
			addPointToLine(xSpacing, (arrays[0].indexOf(item)) * ySpacing + ySpacing)
		}

		if (settings.curvyLines) addPointToLine(xSpacing, (arrays[0].indexOf(item)) * ySpacing + ySpacing)
		for (let step = 0; step < arrays.length; step++) {
			let x = step * xSpacing + xSpacing * (settings.extraLinesAtBeginningAndEnd ? 2 : 1)
			let y = (arrays[step].indexOf(item)) * ySpacing + ySpacing
			addPointToLine(x, y);
		}
		if (settings.curvyLines) addPointToLine(width - xSpacing, itemIndex * ySpacing + ySpacing)

		if (settings.extraLinesAtBeginningAndEnd) {
			addPointToLine(width - xSpacing, itemIndex * ySpacing + ySpacing)
		}
		endShape();

		itemIndex++
	}
	pop()
}

function addPointToLine(x, y) {
	if (settings.curvyLines) {
		curveVertex(x, y)
	} else {
		vertex(x, y)
	}
}

function keyPressed() {
	if (key == "s") {
		saveImage()
	}
}

function saveImage() {
	pixelDensity(6);
	display();
	save()
	pixelDensity(2);

}

function mouseWheel(event) {
	settings.scale -= event.delta * 0.01;
	display();
}
